{
  "public_post": "Important notice: The flour used for this week's loaves was contaminated, so we have stopped production and are working to bake safe bread for tomorrow. Please do NOT eat any co‑op bread today. We apologise for the inconvenience and will keep you updated.",
  "reason": "To protect villagers' health and maintain trust after learning the bread is unsafe."
}

{
  "public_post": "Final notice: All contaminated loaves have been fully refunded; safe flour is now in use and fresh, healthy loaves are available today. Thank you for your patience—if you still feel unwell, please see the clinic.",
  "reason": "To reassure villagers, close the recall, and encourage continued purchases of safe bread."
}
